def horizon_curve():
    import numpy as np
    H = np.logspace(0, np.log10(300), 300)
    for k in (1, 2, 3):
        fig, ax = plt.subplots(figsize=(5.8, 2.45))
        ax.plot(H, 0.99 ** H, color=C['danger'], lw=3)
        ax.text(1.3, 0.2, '99% per step,\nno checks', color=C['danger'], fontsize=12, fontweight='bold')
        for hh, key, dx, dy in ((10, 'p_short_pct', -48, -24), (100, 'p_long_pct', 6, 6)):
            ax.plot([hh], [{'p_short_pct': 0.904382075, 'p_long_pct': 0.3660323413}[key]], 'o', color=C['danger'], ms=8, zorder=5)
            ax.annotate(f"{ {'p_short_pct': '90.4', 'p_long_pct': '36.6'}[key]}%", (hh, {'p_short_pct': 0.904382075, 'p_long_pct': 0.3660323413}[key]), xytext=(dx, dy), textcoords='offset points', fontsize=13, fontweight='bold', color=C['danger'])
        if k >= 2:
            ax.plot(H, (1 - 0.00105305031) ** H, color=C['data'], lw=3)
            ax.text(1.3, 0.52, '0.11% per step: 90% at 100 turns', ha='left', fontsize=12, fontweight='bold', color=C['data'])
        if k >= 3:
            hx = 200
            ax.plot([hx], [0.1339796749], 'o', color=C['danger'], ms=8, zorder=5)
            ax.annotate('twice the turns: 13.4% = 0.366²', (hx, 0.1339796749), xytext=(-16, -4), textcoords='offset points', ha='right', va='center', fontsize=12, fontweight='bold', color=C['text'])
        ax.set_xscale('log')
        ax.set_xticks([1, 10, 100, 300])
        ax.set_xticklabels(['1', '10', '100', '300'])
        ax.minorticks_off()
        ax.set_ylim(0, 1.05)
        ax.set_yticks([0, 0.5, 1.0])
        ax.set_yticklabels(['0%', '50%', '100%'])
        ax.set_xlabel('Horizon H (turns)')
        ax.set_ylabel('Task success')
        sp.save(fig, OUT / f'horizon_step{k}.svg')

