def sixphase():
    P = [(1, 'Context assembly', 'runtime', RUNTIME, 20, 20), (2, 'Model invocation', 'model', MODEL, 320, 20), (3, 'Validate, authorize', 'runtime', RUNTIME, 620, 20), (4, 'Tool execution', 'tool', TOOLS, 620, 210), (5, 'Observation, evidence', 'runtime', RUNTIME, 320, 210), (6, 'Assess vs. contract', 'runtime', RUNTIME, 20, 210)]
    for k in (1, 2, 3):
        s = Svg(900, 420)
        for n, t, who, role, x, y in P:
            op = 1.0 if n <= 3 or k >= 2 else 0.0
            s.box(x, y, 260, 76, role, op=op, sw=3 if role is MODEL else 2)
            s.text(x + 130, y + 33, f'{n}  {t}', 21, 'bold', INK, 'middle', op=op)
            s.text(x + 130, y + 62, who, 21, color=role[2], anchor='middle', op=op)
        s.line(280, 58, 318, 58, GRAY)
        s.line(580, 58, 618, 58, GRAY)
        s.text(299, 48, '', 1)
        if k >= 2:
            s.line(780, 96, 780, 208, RUNTIME[1], sw=4)
            s.text(792, 160, 'authorized', 19, 'bold', RUNTIME[2])
            s.line(620, 248, 582, 248, GRAY)
            s.line(320, 248, 282, 248, GRAY)
            s.line(70, 210, 70, 98, GRAY)
            s.text(80, 160, 'next turn', 19, color=GRAY)
            s.text(600, 312, 'unknown if timed out', 20, italic=True, color=GRAY, anchor='middle')
        if k >= 3:
            s.path('M 680 96 L 680 140 L 460 140 L 460 208', FAULT[1], dash='7 5')
